  form.querySelectorAll('[data-demo-next],[data-demo-back]').forEach(button=>button.onclick=()=>{capture();const step=Number(button.dataset.demoNext||button.dataset.demoBack);if(step===3&&!dateValid())return;demoWizard.step=step;demoReferenceRender();document.querySelector('.demo-steps').scrollIntoView({behavior:'smooth',block:'start'})});
  // Validate explicitly so a hidden mobile step can be shown before focusing its input.
