 const openEditor=(type,id=null)=>{if(type==='chapter'&&!module||type==='lesson'&&!chapter){toast('Select the parent module or chapter first.');return}view.editor={type,id};curriculumManagementRender();document.querySelector('#curriculum-editor').scrollIntoView({behavior:'smooth'})};document.querySelectorAll('[data-curriculum-add]').forEach(button=>button.onclick=()=>openEditor(button.dataset.curriculumAdd));document.querySelectorAll('[data-curriculum-edit]').forEach(button=>button.onclick=()=>openEditor(button.dataset.curriculumEdit,button.dataset.id));
 const form=document.querySelector('#curriculum-editor-form');if(form){document.querySelector('#curriculum-cancel-editor').onclick=()=>{view.editor=null;curriculumManagementRender()};form.onsubmit=e=>{e.preventDefault();if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form)),error=document.querySelector('#curriculum-editor-error'),list=getList(editor.type);if(!data.title.trim()){error.textContent='Enter a title.';return}if(list.some(i=>i.id!==item?.id&&i.title.toLowerCase()===data.title.trim().toLowerCase())){error.textContent='This title already exists within the same parent.';return}if(data.url){try{if(!['https:','http:'].includes(new URL(data.url).protocol))throw Error()}catch{error.textContent='Use an http or https reference URL.';return}}const record={...item,...data,id:item?.id||crypto.randomUUID(),title:data.title.trim()};if(editor.type==='module'){record.chapters=item?.chapters||[];record.prerequisites=item?.prerequisites||[]}if(editor.type==='chapter')record.lessons=item?.lessons||[];if(item)list.splice(list.findIndex(i=>i.id===item.id),1,record);else list.push(record);if(write(key,state)){if(editor.type==='module'){view.module=record.id;view.chapter=null}if(editor.type==='chapter')view.chapter=record.id;view.editor=null;curriculumManagementRender();toast('Curriculum saved locally. Not published.')}}}
 document.querySelectorAll('[data-curriculum-move]').forEach(button=>button.onclick=()=>{const list=getList(button.dataset.curriculumMove),from=list.findIndex(i=>i.id===button.dataset.id),to=from+Number(button.dataset.direction);if(from<0||to<0||to>=list.length)return;[list[from],list[to]]=[list[to],list[from]];if(save())toast('Local curriculum order updated.')});
 document.querySelectorAll('[data-curriculum-delete]').forEach(button=>button.onclick=()=>{const list=getList(button.dataset.curriculumDelete),item=list.find(i=>i.id===button.dataset.id);if(!item)return;const panel=document.createElement('div');panel.className='curriculum-confirm';panel.innerHTML='<h3 style="font-size:13px">Remove this local item?</h3><p>Its nested chapters or lessons will also be removed. This does not change published content.</p><div class="curriculum-controls"><button type="button" data-confirm-remove>Confirm Remove</button><button type="button" data-cancel-remove>Cancel</button></div>';button.closest('.curriculum-module,.curriculum-chapter,.curriculum-lesson').append(panel);button.disabled=true;panel.querySelector('[data-cancel-remove]').onclick=()=>{panel.remove();button.disabled=false};panel.querySelector('[data-confirm-remove]').onclick=()=>{list.splice(list.findIndex(i=>i.id===item.id),1);if(button.dataset.curriculumDelete==='module')modules.forEach(m=>m.prerequisites=m.prerequisites.filter(id=>id!==item.id));view.editor=null;save()}});
 const hasCycle=(graph,start)=>{const visiting=new Set(),done=new Set();const visit=node=>{if(visiting.has(node))return true;if(done.has(node))return false;visiting.add(node);for(const dependency of graph[node]||[])if(visit(dependency))return true;visiting.delete(node);done.add(node);return false};return visit(start)};
 document.querySelector('#curriculum-prereq-form').onsubmit=e=>{e.preventDefault();const form=e.currentTarget,coursePrerequisites=[...form.querySelectorAll('[name="coursePrerequisite"]:checked')].map(input=>input.value),modulePrerequisites=[...form.querySelectorAll('[name="modulePrerequisite"]:checked')].map(input=>input.value),courseGraph=Object.fromEntries(Object.entries(state).map(([id,c])=>[id,c.prerequisites||[]]));courseGraph[course.id]=coursePrerequisites;const moduleGraph=Object.fromEntries(modules.map(m=>[m.id,m.id===module?.id?modulePrerequisites:m.prerequisites]));if(hasCycle(courseGraph,course.id)||module&&hasCycle(moduleGraph,module.id)){document.querySelector('#curriculum-prereq-error').textContent='These prerequisites create a circular dependency. Remove a conflicting prerequisite.';return}curriculum.prerequisites=coursePrerequisites;if(module)module.prerequisites=modulePrerequisites;if(save())toast('Prerequisites saved locally.')};
