let videoAdminView={tab:'library',query:'',course:'All',status:'All',selected:null,playing:null};
function localMediaStore(action,id,value){return new Promise((resolve,reject)=>{const request=indexedDB.open('tura-local-media',1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains('files'))request.result.createObjectStore('files')};request.onerror=()=>reject(request.error);request.onsuccess=()=>{const db=request.result,transaction=db.transaction('files',action==='get'?'readonly':'readwrite'),store=transaction.objectStore('files');let result;const operation=action==='get'?store.get(id):action==='put'?store.put(value,id):store.delete(id);operation.onsuccess=()=>result=operation.result;transaction.oncomplete=()=>{db.close();resolve(result)};transaction.onerror=()=>{db.close();reject(transaction.error)};transaction.onabort=()=>{db.close();reject(transaction.error||Error('Storage cancelled'))}}})}
