 const list=`<section class="revenue-panel"><h2>Transactions · Local Simulations</h2><div class="revenue-filters"><input id="revenue-query" type="search" aria-label="Search transaction previews" placeholder="Search reference, student or course…" value="${escape(view.query)}"><select id="revenue-course-filter" aria-label="Filter transaction course"><option value="All">All Courses</option>${catalogue.map(c=>`<option value="${escape(c.id)}" ${view.course===c.id?'selected':''}>${escape(c.title)}</option>`).join('')}</select><select id="revenue-status-filter" aria-label="Filter transaction simulation status">${['All','Pending simulation','Verified simulation','Rejected simulation'].map(s=>`<option ${view.status===s?'selected':''}>${s}</option>`).join('')}</select></div>${filtered.length?`<div class="revenue-scroll"><table class="revenue-table"><thead><tr><th>Transaction / Student</th><th>Course</th><th>Sample Amount</th><th>Method</th><th>Status</th><th>Action</th></tr></thead><tbody>${filtered.map(t=>`<tr><td>${escape(t.id)}<small>${escape(studentName(t.student))}</small></td><td>${escape(courseName(t.course))}</td><td>${money(t.amount)}</td><td>${escape(t.method)}</td><td><span class="revenue-badge">${t.status}</span></td><td><button data-revenue-select="${escape(t.id)}">View</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="revenue-empty">No matching local financial simulations.</div>'}</section>`;
