 const verification=`<section class="revenue-panel"><h2>Payment Verification · Simulation</h2>${state.transactions.filter(t=>t.status==='Pending simulation').map(t=>`<article class="revenue-row"><div><h3>${escape(studentName(t.student))} · ${money(t.amount)}</h3><p>${escape(courseName(t.course))}<br>${escape(t.reference)}</p><span class="revenue-badge">No bank/provider verification</span></div><div class="revenue-actions"><button class="button secondary" data-revenue-action="verify" data-id="${escape(t.id)}">Mark Verified Simulation</button><button class="button secondary" data-revenue-action="reject" data-id="${escape(t.id)}">Reject Simulation</button></div></article>`).join('')||'<div class="revenue-empty">No pending payment simulations.</div>'}<p class="revenue-note">These actions only label local records. They never confirm a payment with a bank or provider.</p></section>`;
