 const refundPanel=`<section class="revenue-panel"><h2>Refund Simulations</h2>${state.refunds.map(r=>`<article class="revenue-row"><div><h3>${money(r.amount)} · ${escape(r.id)}</h3><p>${escape(r.transaction)}<br>${escape(r.reason)}</p><span class="revenue-badge">${r.status}</span></div>${r.status==='Requested simulation'?`<div class="revenue-actions"><button class="button secondary" data-refund-action="process" data-id="${escape(r.id)}">Process Simulation</button><button class="button secondary" data-refund-action="cancel" data-id="${escape(r.id)}">Cancel Simulation</button></div>`:''}</article>`).join('')||'<p>No refund simulations recorded.</p>'}${selected?.status==='Verified simulation'?`<form id="revenue-refund-form" class="revenue-form" style="margin-top:20px"><h3>Request Refund Simulation · ${escape(selected.id)}</h3><p>Available sample balance: ${money(refundable(selected))}. Pending and processed simulations reserve their amounts.</p><label>Sample refund amount (INR)<input name="amount" type="number" min="0.01" max="${refundable(selected)/100}" step="0.01" required></label><label>Reason<textarea name="reason" maxlength="2000" required></textarea></label><p id="revenue-refund-error" class="revenue-error" role="alert"></p><button class="button">Save Refund Simulation</button></form>`:'<p>Select a verified simulation before preparing a refund preview.</p>'}<p class="revenue-note">No funds are moved. Tax, refund policy and real payment provider services are not connected.</p></section>`;
