  const remember=document.createElement('label');remember.className='stu-auth-remember';remember.innerHTML='<input type="checkbox" name="rememberIdentity"><span>Remember email / phone on this device</span>';form.querySelector('.auth-forgot').before(remember);
  const saved=read('tura-signin-identity',null);if(saved&&typeof saved.value==='string'){const button=document.querySelector(`[data-login-method="${saved.method==='phone'?'phone':'email'}"]`);if(button)button.click();form.elements.identity.value=saved.value;form.elements.rememberIdentity.checked=true}
  form.addEventListener('submit',e=>{if(!form.checkValidity())return;if(form.elements.rememberIdentity.checked)write('tura-signin-identity',{value:form.elements.identity.value,method:form.elements.identity.type==='tel'?'phone':'email'});else try{localStorage.removeItem('tura-signin-identity')}catch{}},true);
