  document.querySelector('#stu-toggle-confirm').onclick=e=>{const input=form.elements.confirmPassword,button=e.currentTarget,visible=input.type==='password';input.type=visible?'text':'password';button.textContent=visible?'Hide':'Show';button.setAttribute('aria-pressed',String(visible));button.setAttribute('aria-label',visible?'Hide confirm password':'Show confirm password')};
