 root.innerHTML=css+(exam?'<div class="stu-exam-tabs"><a href="#dashboard/assessments">← My Assessments</a></div>':'')+body;main.append(root);document.title=`${exam?exam.title:'Assessments & Quizzes'} (STU-EXAM) — Tura Infotech`;
 const refresh=()=>{root.remove();studentAssessmentsModuleRender()};document.querySelectorAll('[data-stu-exam-filter]').forEach(button=>button.onclick=()=>{view.filter=button.dataset.stuExamFilter;refresh()});const courseFilter=document.querySelector('#stu-exam-course-filter');if(courseFilter)courseFilter.onchange=e=>{view.course=e.target.value;refresh()};
 const start=document.querySelector('#stu-exam-start');if(start)start.onclick=()=>{if(draft){location.hash=link(exam,'take','0').slice(1);return}const current=read(key,{}),record=current[exam.id]||{draft:null,attempts:[]};if(record.attempts.length>=3){toast('The three local practice attempts have been used.');return}record.draft={id:crypto.randomUUID(),started:new Date().toISOString(),deadline:new Date(Date.now()+5*60*1000).toISOString(),answers:{}};current[exam.id]=record;if(write(key,current))location.hash=link(exam,'take','0').slice(1)};
