function specimenCertificatePDF(record){
 // Self-contained PDF made only from ASCII text, with explicit specimen labels.
 const clean=value=>String(value).normalize('NFKD').replace(/[^\x20-\x7E]/g,'?').slice(0,100),literal=value=>clean(value).replace(/([\\()])/g,'\\$1');
 const text=(x,y,size,value)=>`BT /F1 ${size} Tf 1 0 0 1 ${x} ${y} Tm (${literal(value)}) Tj ET\n`;
 let content='0.82 0.30 0.61 RG 3 w 25 25 792 545 re S\n0.55 0.18 0.48 rg\n';content+=text(55,520,24,'TURA Infotech & Academy');content+=text(55,480,16,'CERTIFICATE LAYOUT SPECIMEN');content+=text(55,426,30,'SAMPLE - NOT VALID');content+='0.35 0.25 0.40 rg\n';content+=text(55,373,13,'Illustrative layout prepared for:');content+=text(55,340,22,record.name);content+=text(55,300,17,record.courseName);content+=text(55,250,11,'This specimen does not certify achievement, completion or qualification.');content+=text(55,225,11,'No authorised issuer, official signature or verified completion is connected.');content+=text(55,175,10,`Local specimen ID: ${record.id}`);content+=text(55,153,10,`Preview created: ${record.date.slice(0,10)} (not an issue date)`);content+=text(55,115,10,'This file has no credential validity. Verification is browser-local only.');content+=text(55,85,10,'Any non-ASCII characters are transliterated or replaced in this sample PDF.');content+=text(55,57,12,'SAMPLE - NOT VALID - NO COURSE CREDIT');
 const objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 842 595] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>',`<< /Length ${content.length} >>\nstream\n${content}endstream`,'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>'];let pdf='%PDF-1.4\n',offsets=[0];objects.forEach((object,index)=>{offsets.push(pdf.length);pdf+=`${index+1} 0 obj\n${object}\nendobj\n`});const start=pdf.length;pdf+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n`;for(const offset of offsets.slice(1))pdf+=String(offset).padStart(10,'0')+' 00000 n \n';pdf+=`trailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${start}\n%%EOF\n`;return new Blob([pdf],{type:'application/pdf'});
}
