 const detailLink=(t,s='ticket')=>`#dashboard/support/${s}/${t.id}`,dateLabel=t=>t.createdAt?new Date(t.createdAt).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})+' IST':'Creation time not recorded';
 const ticketList=tickets.filter(t=>view.status==='All'||view.status==='Closed locally'&&t.closed||view.status==='Draft'&&!t.closed);
