 const attachForm=(selector,isReply)=>{const form=document.querySelector(selector);if(!form)return;form.onsubmit=async e=>{e.preventDefault();if(!form.reportValidity())return;const values=Object.fromEntries(new FormData(form)),status=document.querySelector(isReply?'#stu-sup-reply-status':'#stu-sup-raise-status'),text=isReply?values.text.trim():values.message.trim();if(!text||!isReply&&!values.title.trim()){status.textContent='Enter meaningful text and a subject where required.';return}const file=form.elements.file.files[0];if(file&&(file.size===0||file.size>10*1024*1024||!['pdf','png','jpg','jpeg','txt'].includes(file.name.split('.').pop().toLowerCase()))){status.textContent='Choose a supported non-empty file up to 10 MB.';return}const button=form.querySelector('button');button.disabled=true;let fileId=null;try{if(file){fileId=`stu-support-${crypto.randomUUID()}`;await localMediaStore('put',fileId,file)}const current=studentLoad(),attachment=file?{id:fileId,name:file.name,size:file.size}:null;let id;if(isReply){id=ticket.id;const target=current.tickets.find(t=>t.id===id);if(!target||target.closed){if(fileId)await localMediaStore('delete',fileId);status.textContent='The local draft was closed or removed. Reopen it first.';return}target.replies=[...(target.replies||[]),{id:crypto.randomUUID(),text,attachment,date:new Date().toISOString()}]}else{id=crypto.randomUUID();current.tickets.push({id,title:values.title.trim(),category:values.category,message:text,closed:false,createdAt:new Date().toISOString(),attachment,replies:[]})}if(!persist(current)){if(fileId)await localMediaStore('delete',fileId);status.textContent='Could not save draft metadata.';return}if(root.isConnected){if(isReply)refresh();else location.hash=`dashboard/support/ticket/${id}`}toast(isReply?'Reply draft saved locally. Not sent.':'Ticket draft saved locally. Not submitted.')}catch{status.textContent='Browser storage is unavailable or full. Try text without an attachment.'}finally{button.disabled=false}}};attachForm('#stu-sup-raise-form',false);attachForm('#stu-sup-reply-form',true);
