 document.querySelectorAll('[data-stu-sup-download]').forEach(button=>button.onclick=async()=>{const id=button.dataset.stuSupDownload,attachment=id==='original'?ticket.attachment:(ticket.replies||[]).find(r=>r.id===id)?.attachment;if(!attachment)return;try{const file=await localMediaStore('get',attachment.id);if(!file){toast('This local attachment is missing from browser storage.');return}const url=URL.createObjectURL(file),link=document.createElement('a');link.href=url;link.download=attachment.name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch{toast('Could not open local attachment storage.')}});
