 if(section==='invoices')panel=`<section class="stu-pay-panel"><h2>Invoices</h2><div class="stu-pay-empty">No valid invoices or payment receipts are connected.</div><p class="stu-pay-note">Demo downloads below are plain-text simulation records, not invoices, tax documents or evidence of payment.</p>${successful.map(r=>`<article class="stu-pay-row"><h3>${escape(courseNames(r))}</h3><p>${escape(r.id)}<br>${escape(date(r))}</p><span class="stu-pay-badge">Not an invoice or receipt</span><div class="stu-pay-actions"><button class="button secondary" data-stu-pay-download="${escape(r.id)}">Download Demo Record (.txt)</button></div></article>`).join('')||'<p>No successful simulations to export.</p>'}</section>`;
 if(section==='status')panel=selected?`<section class="stu-pay-panel"><h2>Payment Status · Local Preview</h2><select id="stu-pay-selected" class="stu-pay-selected" aria-label="Choose checkout simulation">${records.map(r=>`<option value="${escape(r.id)}" ${selected.id===r.id?'selected':''}>${escape(r.id)} · ${label(r)}</option>`).join('')}</select><div class="stu-pay-status-icon" aria-hidden="true">${selected.status==='success'?'✓':selected.status==='failure'?'×':'—'}</div><h3 style="text-align:center">${label(selected)}</h3><p style="text-align:center">${escape(courseNames(selected))}</p><article class="stu-pay-timeline actual"><h3>Local checkout simulation recorded</h3><p>${escape(date(selected))}<br>${escape(selected.id)}</p></article><article class="stu-pay-timeline"><h3>Payment provider verification</h3><p>Unavailable. No bank transaction or verified payment event exists.</p></article><article class="stu-pay-timeline"><h3>Enrollment confirmation</h3><p>Not performed. No course access was granted.</p></article><article class="stu-pay-timeline"><h3>Invoice issuance</h3><p>Not performed. No valid invoice or receipt was created.</p></article><div class="stu-pay-actions"><a class="button secondary" href="#cart">Explore Checkout Preview ↗</a><a class="button secondary" href="#dashboard/support/raise">Prepare Support Draft ↗</a></div></section>`:'<section class="stu-pay-panel"><h2>Payment Status</h2><div class="stu-pay-empty">No local checkout simulations available.</div><div class="stu-pay-actions"><a class="button secondary" href="#cart">Open Course Bag ↗</a></div></section>';
 for(const child of [...main.children])if(child.tagName!=='STYLE'&&!child.classList.contains('student-portal-topbar')&&!child.classList.contains('student-notice'))child.remove();
 const root=document.createElement('div');root.className='stu-pay-content';root.innerHTML=css+`<div class="stu-pay-welcome"><div><h1>My Payments</h1><p>Review enrolment availability and browser-local checkout records.<br>No actual payments or invoices are connected.</p></div><div class="stu-pay-stats">${[['—','Verified enrolments'],[records.length,'Local checkout simulations'],['—','Valid invoices']].map(([value,label])=>`<div class="stu-pay-stat"><b>${value}</b><small>${label}</small></div>`).join('')}</div></div><nav class="stu-pay-tabs" aria-label="Student payment sections">${tabs.map(([id,label])=>`<a href="#dashboard/payments/${id}" ${section===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="stu-pay-grid"><div>${panel}</div><aside><section class="stu-pay-panel"><h2>Payment Summary</h2><div class="stu-pay-ring"><div><b>—</b><small>Verified amounts<br>unavailable</small></div></div>${[['Real paid amount','Unavailable'],['Real pending balance','Unavailable'],['Successful local simulations',successful.length],['Failed local simulations',records.filter(r=>r.status==='failure').length]].map(([label,value])=>`<div class="stu-pay-detail-row"><span>${label}</span><span>${value}</span></div>`).join('')}<p class="stu-pay-note">No monetary total is inferred from simulation outcomes. Course prices, taxes, payment providers and authenticated transaction records need integration.</p></section><section class="stu-pay-panel"><h2>Payment Help</h2><p>Do not enter card details, bank credentials or OTPs in a local support draft.</p><a class="button secondary" href="#dashboard/support">Student Support ↗</a></section></aside></div>`;main.append(root);document.title='My Payments (STU-PAY) — Tura Infotech';
 const refresh=()=>{root.remove();studentPaymentsModuleRender()};document.querySelectorAll('[data-stu-pay-filter]').forEach(button=>button.onclick=()=>{view.filter=button.dataset.stuPayFilter;refresh()});const selector=document.querySelector('#stu-pay-selected');if(selector)selector.onchange=e=>{view.selected=e.target.value;location.hash=`dashboard/payments/status/${e.target.value}`};
