 for(const child of [...main.children])if(child.tagName!=='STYLE'&&!child.classList.contains('student-portal-topbar')&&!child.classList.contains('student-notice'))child.remove();
 const root=document.createElement('div');root.className='stu-profile-content';root.innerHTML=css+`<div class="stu-profile-welcome"><div><h1>My Profile</h1><p>View and manage local personal details,<br>photo and account preferences.</p></div><div class="stu-profile-stats">${[['—','Enrolled courses'],['—','Earned certificates'],['Local','Profile draft only']].map(([value,label])=>`<div class="stu-profile-stat"><b>${value}</b><small>${label}</small></div>`).join('')}</div></div><nav class="stu-profile-tabs" aria-label="Student profile sections">${tabs.map(([id,label])=>`<a href="#dashboard/profile/${id}" ${section===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="stu-profile-grid"><div>${panel}</div><aside><section class="stu-profile-panel stu-profile-card">${avatar}<h2>${escape(display)}</h2><span class="stu-profile-badge">Local student profile · no account signed in</span><p>${escape(profile.email||'Email not supplied')}</p><div class="stu-profile-actions" style="justify-content:center"><a class="button secondary" href="#dashboard/profile/photo">Update Photo ↗</a></div></section><section class="stu-profile-panel"><h2>Quick Actions</h2><div class="stu-profile-quick"><a href="#dashboard/profile/edit">Edit Profile →</a><a href="#dashboard/profile/photo">Profile Photo →</a><a href="#dashboard/profile/password">Change Password Preview →</a><a href="#dashboard/profile/settings">Account Settings →</a></div></section></aside></div>`;main.append(root);document.title='My Profile (STU-PRO) — Tura Infotech';studentProfilePhotoRefine();
