 const refresh=()=>{delete root.dataset.crs001;selfPacedCourses001Render()};document.querySelectorAll('[data-crs001-tab]').forEach(button=>button.onclick=()=>{view.tab=button.dataset.crs001Tab;refresh()});const all=document.querySelector('#crs001-show-all');if(all)all.onclick=()=>{Object.assign(view,{tab:'all',query:'',status:'All',category:'All'});refresh()};document.querySelector('#crs001-query').oninput=e=>{const caret=e.target.selectionStart;view.query=e.target.value;refresh();const input=document.querySelector('#crs001-query');input.focus();input.setSelectionRange(caret,caret)};for(const [selector,key]of [['#crs001-status','status'],['#crs001-category','category'],['#crs001-sort','sort']])document.querySelector(selector).onchange=e=>{view[key]=e.target.value;refresh()};
