 document.querySelectorAll('[data-crs001-continue]').forEach(button=>button.onclick=()=>{const id=button.dataset.crs001Continue,course=courses.find(c=>c.id===id),reading=read(`tura-learning-preview-${id}`,{}),video=read(`tura-student-video-preview-${id}`,{}),next=course.modules.findIndex((_,i)=>!(reading.completed||[]).includes(i)&&!video.lessons?.[String(i)]?.complete);studentVideoView.course=id;studentVideoView.lesson=Math.max(0,next);location.hash=`learn/video/${id}`});
