 if(p[0]==='dashboard'&&p[1]==='lessons'&&!main.querySelector('#vid001-entry')){const a=document.createElement('a');a.id='vid001-entry';a.href='#dashboard/video-player/data-analytics';a.textContent='Open Video Player · STU-VID-001 →';a.style.cssText='display:block;padding:15px;color:#c00083';main.append(a)}
 if(p[0]!=='dashboard'||!['video-player','lesson-playlist','video-notes'].includes(p[1]))return;
