 const v=bookmarks004View,rows=[];courses.forEach(c=>{const key=`tura-video-player-001-${c.id}`,data=read(key,{lessons:{}});Object.entries(data.lessons||{}).forEach(([lesson,r])=>{if(!c.modules[Number(lesson)])return;(r.bookmarks||[]).forEach((b,n)=>rows.push({id:`${c.id}-${lesson}-${n}`,course:c,lesson:Number(lesson),type:'timestamp',label:b.label||'Timestamp bookmark',time:Number(b.time)||0,key,n}));});c.modules.forEach((_,m)=>{for(let ch=0;ch<3;ch++)for(let l=0;l<6;l++){const k=`tura-student-lesson-details-${c.id}-${m}-${ch}-${l}`,r=read(k,null);if(r?.bookmarked)rows.push({id:k,course:c,lesson:m,chapter:ch,detail:l,type:'lesson',label:r.bookmarkLabel||`Lesson ${m+1}.${ch+1}.${l+1}`,key:k})}})});
