// STU-VID-005: selective downloads of the available illustrative resources.
function downloadResources005Decorate(root,course,resources,isDownloads){
 const nav=root.querySelector('.rs007-nav');if(nav){const a=document.createElement('a');a.href=`#dashboard/courses/${course.id}/downloads`;a.textContent='Download Resources';if(isDownloads){nav.querySelectorAll('.active').forEach(x=>x.classList.remove('active'));a.className='active'}nav.append(a)}
 if(!isDownloads)return;
 const kicker=root.querySelector('.rs007-banner small');if(kicker)kicker.textContent='STU-VID-005 · DOWNLOAD RESOURCES';const subtitle=root.querySelector('.rs007-banner p');if(subtitle)subtitle.textContent='Preview, select and download sample study resources for this course.';
 const table=root.querySelector('.rs007-table');if(!table)return;const head=document.createElement('th');const all=document.createElement('input');all.type='checkbox';all.setAttribute('aria-label','Select all visible resources');all.style.width='auto';head.append(all);table.querySelector('thead tr').prepend(head);
 const selections=[];table.querySelectorAll('tbody tr').forEach((tr,n)=>{if(!resources[n]){const cell=tr.querySelector('td');if(cell)cell.colSpan=5;return}const td=document.createElement('td'),check=document.createElement('input');check.type='checkbox';check.style.width='auto';check.setAttribute('aria-label',`Select ${resources[n].title}`);td.append(check);tr.prepend(td);selections.push({check,resource:resources[n]})});
 const controls=document.createElement('div');controls.className='rs007-toolbar';controls.style.cssText='padding:15px 0;border-top:1px solid #eadcf8;flex-wrap:wrap';const count=document.createElement('span'),button=document.createElement('button'),clear=document.createElement('button');button.className='rs007-primary';clear.textContent='Clear Selection';controls.append(count,button,clear);table.parentElement.after(controls);
 const update=()=>{const selected=selections.filter(x=>x.check.checked);count.textContent=`${selected.length} selected`;button.textContent=`Download Selected (${selected.length})`;button.disabled=!selected.length;all.checked=selections.length>0&&selected.length===selections.length;all.indeterminate=selected.length>0&&selected.length<selections.length};
 selections.forEach(x=>x.check.onchange=e=>{e.stopPropagation();update()});all.onchange=e=>{e.stopPropagation();selections.forEach(x=>x.check.checked=all.checked);update()};clear.onclick=e=>{e.stopPropagation();selections.forEach(x=>x.check.checked=false);update()};
 button.onclick=e=>{e.stopPropagation();const selected=selections.filter(x=>x.check.checked);if(!selected.length)return;const body=`TURA — SAMPLE RESOURCE BUNDLE\nNot official course materials\nCourse: ${course.name||course.title||course.id}\n\n${selected.map(x=>x.resource.body).join('\n\n--------------------\n\n')}`,url=URL.createObjectURL(new Blob([body],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='tura-selected-sample-resources.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};update();
 const note=document.createElement('p');note.className='rs007-muted';note.textContent='Selected resources download as one TXT bundle. Individual previews and downloads remain available in each row. Selection resets when filters change; official PDFs, slides and datasets are not connected.';controls.after(note);
}

